// Copy of src/kb.mjs generated by scripts/build-index.mjs — do not edit.
// Search engine over the generated Pharos documentation index.
//
// The index is a build artifact (see scripts/build-index.mjs) fetched from
// https://docs.pharos.xyz/llms.txt. Nothing here invents content: every result
// carries the official page URL and markdown URL it came from.
//
// Ranking is BM25 over weighted fields (title > headings > description > id >
// body) plus a phrase bonus. Small enough to run in a Worker, a CLI, or a
// browser tab with no dependencies.

import { DOCS, INDEX_META } from "./index.generated.js";

export { DOCS, INDEX_META };

// BM25 constants, chosen with scripts/tune.mjs over the labelled set and then
// checked against the two held-out sets, which did not move when these changed.
// b sits at 0.82 rather than the textbook 0.75 because the corpus mixes 40-word
// parameter tables with 4000-word API dumps: without a heavy length penalty the
// long pages win every query they happen to contain the words for.
const K1 = 0.6;
const B = 0.82;
const FIELD_WEIGHTS = { title: 5.0, headings: 3.0, description: 2.0, id: 1.6, text: 1.0 };
const SNIPPET_RADIUS = 170;
// Weight of the definition-page bonus, the length below which a page is too
// small to be a real reference table, how much of the query (weighted by term
// rarity) a page must cover to earn the bonus, and how much information the
// query itself must carry before brevity is allowed to matter.
const DEFINITION_WEIGHT = 8;
const MIN_DEFINITION_TOKENS = 24;
const MIN_DEFINITION_COVERAGE = 0.8;
const MIN_QUERY_IDF = 1.0;
const MIN_TERM_DENSITY = 0.01;

const STOPWORDS = new Set([
  "a", "about", "an", "and", "any", "are", "as", "at", "be", "by", "can", "do", "does",
  "for", "from", "get", "give", "how", "i", "in", "into", "is", "it", "its", "me", "my",
  "of", "on", "or", "should", "show", "tell", "that", "the", "there", "these", "this",
  "to", "use", "using", "want", "was", "what", "when", "where", "which", "who", "why",
  "will", "with", "you", "your", "explain", "please", "help", "need",
  // Quantifiers that ask about magnitude without naming anything. "how much
  // does a transaction cost" is a question about gas; leaving "much" in the
  // query let a marketing page that says "no matter how much" outrank it.
  "much", "many",
  // Question scaffolding. These are rare enough in the corpus to carry high
  // idf, which makes them actively harmful: "what tokens exist on testnet"
  // weighted "exist" (df 4, idf 2.8) as the second most important word and
  // pushed the token registry below a page that merely repeats "testnet".
  // They never name the subject of a question, so they are dropped from the
  // query — the corpus is untouched.
  "exist", "exists", "mean", "means", "difference", "differences", "work",
  "works", "working", "happen", "happens", "able", "actually", "really",
  "exactly", "versus", "vs"
]);

// Domain vocabulary that natural-language questions use but docs spell differently.
// Kept deliberately small and auditable — no fuzzy guessing.
const ALIASES = {
  chainid: ["chain", "id"],
  rpc: ["rpc", "endpoint"],
  endpointurl: ["rpc"],
  testnet: ["atlantic"],
  mainnet: ["pacific"],
  gasfee: ["gas", "fee"],
  gasprice: ["gas"],
  smartcontract: ["contract"],
  solidity: ["foundry", "contract"],
  staking: ["validator", "stake"],
  stake: ["staking", "validator"],
  nft: ["token", "erc721"],
  erc20: ["token", "standard"],
  deploy: ["deploy", "deployment"],
  deployment: ["deploy"],
  walletconnect: ["wallet"],
  faucet: ["gas", "testnet"],
  indexer: ["indexing"],
  oracle: ["oracles"],
  bridge: ["cross", "chain"],
  multisig: ["safe"],
  skillengine: ["skill", "engine"],
  mcp: ["mcp", "model", "context", "protocol"],
  dryrun: ["simulation", "estimate"],
  estimate: ["gas"],
  errors: ["revert", "error"],
  revert: ["error", "revert"],
  install: ["setup", "install"],
  node: ["node", "validator"],
  // The docs page is titled "FAQs"; people type the words out.
  question: ["faq"], faq: ["question"],
  manage: ["management"], management: ["manage"],
  config: ["configuration"], configuration: ["config"]
};

// Names people use that the documentation never writes down. The Pharos docs
// describe getting testnet PROS but the word "faucet" appears on no page, so
// "faucet" degraded into an alias for "gas testnet" and opened the fee
// mechanics page. Aliases cannot fix this — there is nothing in the corpus to
// point at. A short intent table can, and it is small enough to audit: one
// line per colloquialism, each with the page it names.
const INTENTS = {
  faucet: "getting-started/get-pros-gas",
  tap: "getting-started/get-pros-gas"
};
const INTENT_BOOST = 1.5;

function normalize(text) {
  return String(text || "").toLowerCase();
}

// Plurals are folded so "tokens" and "token" are one term. Without this the
// vocabulary carries both spellings with different document frequencies, and a
// query in one number cannot reach a page written in the other: "wallet
// providers" missed "Wallet" because the section page only says "providers".
// Only trailing -s is folded; -ing/-ment/-tion are left alone, because a
// half-Porter that turns "pruning" into "prun" but not "prune" makes things
// worse than doing nothing. Token mixups between distinct words are handled by
// the alias table, which is auditable.
function foldPlural(token) {
  if (token.length <= 3) return token;
  if (/[^aeiou]ies$/.test(token)) return `${token.slice(0, -3)}y`;
  if (/(?:ses|xes|zes|ches|shes)$/.test(token)) return token.slice(0, -2);
  if (/[^s]s$/.test(token)) return token.slice(0, -1);
  return token;
}

export function tokenize(text) {
  const source = String(text || "");
  // "ChainID" and "maxPriorityFeePerGas" are single words to a regex but two and
  // five words to a reader. Index both spellings so "chain id" finds ChainID and
  // "priority fee" finds maxPriorityFeePerGas, while the compound stays findable.
  const compoundSplit = source
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/([A-Z]+)([A-Z][a-z])/g, "$1 $2");
  const out = [];
  const variants = compoundSplit === source ? [source] : [source, compoundSplit];
  for (const variant of variants) {
    const raw = normalize(variant)
      .replace(/[^a-z0-9_.\-\s]/g, " ")
      .split(/\s+/)
      .filter(Boolean);
    for (const token of raw) {
      const cleaned = token.replace(/^[.\-]+|[.\-]+$/g, "");
      if (!cleaned) continue;
      // Keep dotted/hyphenated identifiers searchable both whole and in parts.
      out.push(foldPlural(cleaned));
      if (/[.\-_]/.test(cleaned)) {
        for (const part of cleaned.split(/[.\-_]+/)) if (part.length > 2) out.push(foldPlural(part));
      }
    }
  }
  return out;
}

export function queryTerms(query) {
  const base = tokenize(query).filter((t) => t.length > 1 && !STOPWORDS.has(t));
  const expanded = new Set(base);
  for (const term of base) {
    const squeeze = term.replace(/[_\-.]/g, "");
    if (ALIASES[squeeze]) for (const alias of ALIASES[squeeze]) expanded.add(alias);
    if (ALIASES[term]) for (const alias of ALIASES[term]) expanded.add(alias);
  }
  // "chain id" is also the compound "ChainID", and the docs use both spellings.
  // Documents that spell it as one word carry the rarer token, so this is what
  // lets the Pacific Mainnet parameter table outrank pages that merely say
  // "chain" often. It is scored, but kept out of coverage: a page that answers
  // with the spaced spelling is still a good answer.
  const uniqueBase = [...new Set(base)];
  const compound = uniqueBase.length > 1 ? uniqueBase.join("") : "";
  if (compound.length > 3) expanded.add(compound);
  return { base, all: [...expanded], compound };
}

function termFrequency(tokens) {
  const tf = new Map();
  for (const token of tokens) tf.set(token, (tf.get(token) || 0) + 1);
  return tf;
}

// --- index-time precomputation -------------------------------------------

const CORPUS = DOCS.map((doc) => {
  const fields = {
    title: termFrequency(tokenize(doc.title)),
    headings: termFrequency(tokenize(doc.headings.join(" "))),
    description: termFrequency(tokenize(doc.description)),
    id: termFrequency(tokenize(doc.id.replace(/[/\-_.]/g, " "))),
    text: termFrequency(tokenize(doc.plain || doc.text))
  };
  const lengths = Object.fromEntries(
    Object.entries(fields).map(([field, tf]) => [field, [...tf.values()].reduce((a, b) => a + b, 0) || 0])
  );
  return {
    doc,
    fields,
    lengths,
    searchable: normalize([doc.title, doc.description, doc.headings.join(" "), doc.plain || doc.text, doc.id].join(" "))
  };
});

const AVG_LEN = {};
for (const field of Object.keys(FIELD_WEIGHTS)) {
  const total = CORPUS.reduce((acc, entry) => acc + entry.lengths[field], 0);
  AVG_LEN[field] = total / CORPUS.length || 1;
}

const DOC_FREQ = new Map();
for (const entry of CORPUS) {
  const seen = new Set();
  for (const field of Object.keys(FIELD_WEIGHTS)) {
    for (const term of entry.fields[field].keys()) seen.add(term);
  }
  for (const term of seen) DOC_FREQ.set(term, (DOC_FREQ.get(term) || 0) + 1);
}

function idf(term) {
  const df = DOC_FREQ.get(term) || 0;
  return Math.log(1 + (CORPUS.length - df + 0.5) / (df + 0.5));
}

// --- public API -----------------------------------------------------------

export function listSections() {
  return INDEX_META.sections.slice();
}

export function getDoc(id) {
  if (!id) return null;
  const want = String(id).trim().replace(/^\/+/, "").replace(/\.md$/, "");
  return DOCS.find((doc) => doc.id === want) || null;
}

export function searchDocs(query, options = {}) {
  const opts = typeof options === "number" ? { limit: options } : options || {};
  const requested = Number(opts.limit);
  const limit = Number.isFinite(requested) ? Math.max(1, Math.min(Math.trunc(requested), 50)) : 5;
  const section = opts.section || opts.category || null;

  let pool = CORPUS;
  if (section && section.toLowerCase() !== "all") {
    const want = section.toLowerCase();
    pool = pool.filter((entry) => entry.doc.section.toLowerCase() === want);
  }

  const trimmed = String(query || "").trim();
  // An empty query has no answer. Returning the first N pages would look like a
  // match list to any caller that does not re-check the input; callers that want
  // a listing should read DOCS directly.
  if (!trimmed) return [];

  const { base, all, compound } = queryTerms(trimmed);
  if (all.length === 0) return [];
  // Raw query tokens (stopwords included) are used for "does the query name
  // this page's title" checks — "how do I write my first NFT" names the page.
  const rawTokens = new Set(tokenize(trimmed));

  const scored = [];
  for (const entry of pool) {
    let score = 0;
    const matchedTerms = [];

    for (const term of all) {
      const weight = base.includes(term) || term === compound ? 1 : 0.6;
      let termScore = 0;
      for (const [field, fieldWeight] of Object.entries(FIELD_WEIGHTS)) {
        const tf = entry.fields[field].get(term);
        if (!tf) continue;
        const lenNorm = entry.lengths[field] / AVG_LEN[field];
        const denom = tf + K1 * (1 - B + B * lenNorm);
        termScore += fieldWeight * idf(term) * ((tf * (K1 + 1)) / denom);
      }
      if (termScore > 0) {
        score += termScore * weight;
        matchedTerms.push(term);
      }
    }

    // Title coverage: when the query names the page's subject outright, that
    // page should lead. "chain id and rpc for pacific mainnet" must resolve to
    // the Pacific Mainnet page, not to a guide that merely mentions those words
    // in a table. Partial coverage only nudges; full coverage multiplies.
    const titleTokens = new Set(tokenize(entry.doc.title));
    if (titleTokens.size) {
      let covered = 0;
      for (const token of titleTokens) if (rawTokens.has(token)) covered++;
      const coverage = covered / titleTokens.size;
      score += 7 * coverage;
      if (coverage === 1 && titleTokens.size >= 2) score *= 1.75;
    }

    // Whole-phrase bonus: a query that appears verbatim is a strong signal.
    const phrase = normalize(trimmed).replace(/\s+/g, " ");
    if (phrase.length > 3) {
      const fields = [
        [normalize(entry.doc.title), 14],
        [normalize(entry.doc.headings.join(" ")), 8],
        [normalize(entry.doc.description), 6],
        [entry.searchable, 3]
      ];
      for (const [haystack, bonus] of fields) {
        if (haystack.includes(phrase)) {
          score += bonus;
          break;
        }
      }
    }

    // Query coverage, weighted by term rarity: missing a rare operative word
    // ("stake") must hurt more than missing a common one ("wallet"). Without
    // this, a page that only repeats the object of the question outranks the
    // page that actually answers it.
    const uniqueBase = [...new Set(base)];
    let idfTotal = 0;
    let idfHit = 0;
    for (const term of uniqueBase) {
      const weight = idf(term);
      idfTotal += weight;
      if (matchedTerms.includes(term)) idfHit += weight;
    }
    const coverage = idfTotal > 0 ? idfHit / idfTotal : 0;
    if (uniqueBase.length > 1) score *= 0.35 + 0.65 * coverage;

    // Definition-page bonus. A short page that answers the whole query is
    // usually the reference table the user wants — "chain id" wants the
    // forty-token Network Information block, not a 4000-token methods list
    // that repeats chainId twenty times. BM25 cannot see this: it counts how
    // much of the query is in the page, never how much of the page is about the
    // query, and absolute term counts always favour the long document.
    //
    // Two gates keep it honest:
    //   - the query must carry information (idf mass >= MIN_QUERY_IDF), so a
    //     bare "network" does not start promoting whatever page is shortest;
    //   - the page must cover the query almost entirely, weighted by rarity, so
    //     dropping "usdc" is disqualifying while dropping "contract" is not.
    const bodyTokens = entry.lengths.text;
    // For a one-word query, coverage is trivially satisfied by any page that
    // mentions the word once, so the brevity bonus needs a second gate or the
    // shortest passing mention wins: "faucet" started preferring the 300-token
    // gas model over the 672-token faucet page. Require the page to be *about*
    // the term — named in its title/headings, or dense enough in the body that
    // it is a table label rather than a passing reference.
    const onlyTerm = uniqueBase.length === 1 ? uniqueBase[0] : null;
    const density = onlyTerm
      ? (bodyTokens > 0 ? (entry.fields.text.get(onlyTerm) || 0) / bodyTokens : 0)
      : 1;
    const aboutIt =
      onlyTerm === null ||
      Boolean(entry.fields.title.get(onlyTerm) || entry.fields.headings.get(onlyTerm)) ||
      density >= MIN_TERM_DENSITY;
    if (
      bodyTokens >= MIN_DEFINITION_TOKENS &&
      idfTotal >= MIN_QUERY_IDF &&
      coverage >= MIN_DEFINITION_COVERAGE &&
      aboutIt
    ) {
      const brevity = Math.max(0, 1 - bodyTokens / AVG_LEN.text);
      score += DEFINITION_WEIGHT * brevity * coverage;
    }

    if (score > 0) {
      const intent = base.find((t) => INTENTS[t.replace(/[_\-.]/g, "")] === entry.doc.id);
      scored.push({
        ...entry.doc,
        score: Math.round(score * (intent ? INTENT_BOOST : 1) * 100) / 100,
        intent: intent || null,
        matchedTerms: [...new Set(matchedTerms)],
        snippet: buildSnippet(entry.doc, base.length ? base : all)
      });
    }
  }

  scored.sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
  return scored.slice(0, limit);
}

function buildSnippet(doc, terms) {
  // `plain` is the whitespace-normalised copy built by scripts/build-index.mjs.
  // Lowercasing (not normalising) keeps offsets aligned with the original text
  // so the slice preserves the document's real casing.
  const text = doc.plain || doc.text;
  const lowered = text.toLowerCase();
  let at = -1;
  for (const term of terms) {
    const idx = lowered.indexOf(term);
    if (idx !== -1 && (at === -1 || idx < at)) at = idx;
  }
  if (at === -1) return doc.description || text.slice(0, 240);
  const start = Math.max(0, at - SNIPPET_RADIUS);
  const end = Math.min(text.length, at + SNIPPET_RADIUS);
  const slice = text.slice(start, end).replace(/\s+/g, " ").trim();
  return `${start > 0 ? "…" : ""}${slice}${end < text.length ? "…" : ""}`;
}

/** How much the offline index actually knows about this question. */
export function assessConfidence(results, query) {
  if (!results.length) {
    return {
      level: "none",
      reason: "no page in the offline index matched these terms",
      hint: "use `pharos-docs ask \"<question>\"` to query the live documentation"
    };
  }
  const { base } = queryTerms(query);
  const top = results[0];
  const covered = base.length ? base.filter((t) => top.matchedTerms.includes(t)).length / base.length : 0;
  if (top.score >= 30 && covered >= 0.5) {
    return { level: "high", reason: `top page covers ${Math.round(covered * 100)}% of query terms` };
  }
  if (top.score >= 12) {
    return { level: "medium", reason: "related pages found, but the question may need the live docs" };
  }
  return {
    level: "low",
    reason: "only weak term overlap — the index may not cover this",
    hint: "use `pharos-docs ask \"<question>\"` for a grounded answer from the live documentation"
  };
}

/** Bounded Levenshtein — returns the distance, or null when it exceeds `max`. */
function editDistance(a, b, max) {
  if (Math.abs(a.length - b.length) > max) return null;
  let previous = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i += 1) {
    const current = [i];
    let best = current[0];
    for (let j = 1; j <= b.length; j += 1) {
      current[j] = Math.min(
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)
      );
      best = Math.min(best, current[j]);
    }
    if (best > max) return null;
    previous = current;
  }
  return previous[b.length] <= max ? previous[b.length] : null;
}

let VOCABULARY = null;

/** Term → corpus frequency, built once from the indexed text. */
function vocabulary() {
  if (VOCABULARY) return VOCABULARY;
  const counts = new Map();
  for (const entry of CORPUS) {
    for (const [term, tf] of entry.fields.text) counts.set(term, (counts.get(term) || 0) + tf);
  }
  VOCABULARY = counts;
  return VOCABULARY;
}

/** "Did you mean" for terms the corpus has never seen — real vocabulary only. */
export function suggestTerms(query, max = 5) {
  const { all } = queryTerms(query);
  const vocab = vocabulary();
  const found = new Map();
  for (const term of all) {
    if (vocab.has(term) || term.length < 4) continue;
    let best = null;
    for (const [candidate, count] of vocab) {
      if (candidate[0] !== term[0] || candidate.length < 4) continue;
      if (editDistance(term, candidate, 2) === null) continue;
      if (!best || count > best.count) best = { candidate, count };
    }
    if (best) found.set(best.candidate, best.count);
  }
  return [...found.entries()].sort((a, b) => b[1] - a[1]).slice(0, max).map(([term]) => term);
}

/** Result shape shared by the CLI, the API and MCP-style tool callers. */
export function toToolResult(query, results, extras = {}) {
  const confidence = assessConfidence(results, query);
  const payload = {
    success: true,
    query,
    source: INDEX_META.source,
    index: { pages: INDEX_META.pageCount, contentHash: INDEX_META.contentHash, generatedAt: INDEX_META.generatedAt },
    confidence,
    total: results.length,
    results: results.map((doc) => ({
      id: doc.id,
      title: doc.title,
      section: doc.section,
      url: doc.url,
      mdUrl: doc.mdUrl,
      headings: doc.headings,
      snippet: doc.snippet,
      score: doc.score,
      matchedTerms: doc.matchedTerms
    }))
  };
  if (confidence.level === "none" || confidence.level === "low") {
    const suggestions = suggestTerms(query);
    if (suggestions.length) payload.suggestions = suggestions;
  }
  return { ...payload, ...extras };
}
